        "binding": {
          "name": "data.connectorMode.operation.params.documents",
          "type": "zeebe:input"
        },
        "condition": {
          "allMatch": [
            {
              "property": "data.connectorMode.operation.type",
              "equals": "sendMessage",
              "type": "simple"
            },
            {
              "property": "data.connectorMode.type",
              "equals": "standalone",
              "type": "simple"
            }
          ]
        },
        "type": "String"
